dtsPropsFor.Art:
/** Colour and motif record the SVG scene is generated from. */
art: {
  /** Background base colour, hex. */
  sky?: string;
  /** Foreground / highlight colour, hex. */
  accent?: string;
  /** Which scene to draw. Undrawn motifs fall through to the stripe placeholder. */
  motif?:
    | 'brass' | 'mural' | 'rowhouse' | 'skyline' | 'oak'
    | 'waves' | 'palm' | 'dune' | 'ferry' | 'ridge';
};
/** Names the photograph this art stands in for. Rendered as a monospace chip
 *  and used as the SVG's accessible label, so it is required. */
caption: string;
/** 'art--tall' (3:4) or 'art--wide' (16:9). Omit for the 4:3 default.
 *  Shape comes from CSS — Art fills whatever box it is given. */
className?: string;

dtsPropsFor.EstimateBadge:
/** Label text. Defaults to 'Estimated prototype data'.
 *  Must stay visible anywhere a price appears — every price in this app
 *  is invented, and the badge is what says so. */
children?: React.ReactNode;
